-- ============================================================================
-- V2026_07_31_05__rate_card_egypt.sql
-- Egypt (EG) interchange rate card. Phase-2 multi-country engine
-- (V2026_07_31_02) resolves this by tenant.home_country_code = 'EG'.
--
-- SOURCE: Egypt business-case workbook (POS Fee table / ECOM Fee table),
-- 387 MCCs each. Only the LOCAL Visa + MasterCard interchange is taken from the
-- file (per instruction). INTERNATIONAL is the constant flat 1.85% (per UAE).
-- Benefit / other local schemes are intentionally NOT seeded (no ref_card_scheme
-- entry / no feed mapping yet). Scheme fees are NOT in this file: the UAE
-- scheme-fee grid is copied unchanged (below).
--
-- MODEL: country-level rows (tenant_id NULL = shared by every EG tenant).
--   dest INTERNATIONAL : flat 1.85% (priority 1, scheme-agnostic).
--   dest DOMESTIC      : per (scheme_group, channel, mcc) from the file
--                        (priority 60), plus a scheme/channel wildcard default
--                        (priority 15, mcc NULL) at the modal rate for any MCC
--                        not present in the file. card_type/tier = wildcard.
--   JCB / UnionPay     : domestic flat 1.75% (priority 65, per UAE); intl uses
--                        the flat 1.85%. Scheme fees for JCB/UPI come from the
--                        copied UAE grid (flat 0.05%).
--   ANY-SCHEME FALLBACK: a domestic txn NOT identified as Visa/MC/JCB/UnionPay
--                        uses, for that MCC, the HIGHER of the Visa/MC local
--                        rate (scheme_group NULL, priority 40 per-MCC /
--                        priority 10 default) — e.g. domestic Amex.
-- interchange_pct is stored POSITIVE (file values are negative costs).
-- cap_amount NULL (file gives no caps); cap_currency_code 'EGP'.
--
-- SKIPPED (flat per-transaction fee, no flat-fee model — same gap as UAE
-- 8398/8661 '25 Cents'): those MCC/scheme/channel cells get the domestic
-- wildcard rate instead. See migration report.
--
-- Splitter-safe (no dollar-quoting). Idempotent: the interchange seed is guarded by
-- NOT EXISTS (country has zero country-level rows); the scheme-fee copy by
-- NOT EXISTS (country has zero scheme rows). In-UI rate edits are never
-- clobbered. BACKFILL: fees compute at ingest — re-ingest EG months.
-- ============================================================================

-- Interchange rate card (guarded: seed only when EG has no country-level rows).
INSERT INTO interchange_rate_local
    (tenant_id, country_code, cap_currency_code, priority, dest, channel, scheme_group,
     card_type, tier, mcc_sector, mcc, min_ticket, max_ticket, interchange_pct, cap_amount, label)
SELECT v.* FROM ( VALUES
  -- First row carries explicit casts: columns that are NULL in EVERY row
  -- (tenant_id, ticket bounds, cap) otherwise resolve to TEXT under VALUES
  -- common-type inference and the INSERT fails against INT/NUMERIC targets.
  (NULL::INT, 'EG', 'EGP', 1, 'INTERNATIONAL', NULL, NULL, NULL, NULL, NULL, NULL, NULL::NUMERIC, NULL::NUMERIC, 0.018500, NULL::NUMERIC, 'Intl flat 1.85 (constant per UAE)'),
